#Question 1
start &lt;- min(NETFLIX_DATA$period_start)
end &lt;- max(NETFLIX_DATA$period_end)

#Question 2
shows &lt;- nrow(NETFLIX_DATA)

#Question 3
bridgerton &lt;- NETFLIX_DATA |&gt; 
  filter(str_detect(title, "Bridgerton")) |&gt;
  pull(hours_viewed) |&gt;
  sum()

#Question 4
stranger &lt;- NETFLIX_DATA |&gt; filter(str_detect(title, "Stranger Things")) |&gt; 
    filter_out(str_detect(title, "Beyond Stranger Things")) |&gt; 
    filter_out(str_detect(title, "Stranger Things: Fireplace")) |&gt;
    filter_out(str_detect(title, "Stranger Things: Tales From '85")) |&gt; 
    pull(hours_viewed) |&gt;
    sum()

#Question 5
top10_hours &lt;- NETFLIX_DATA |&gt; filter(period == "2026H1") |&gt; 
  arrange(desc(hours_viewed)) |&gt; 
  slice(1:10) |&gt;
  pull(hours_viewed) |&gt;
  sum()

total_hours &lt;- NETFLIX_DATA |&gt; filter(period == "2026H1") |&gt;
  pull(hours_viewed) |&gt;
  sum()

top10_percent &lt;- top10_hours/total_hours

#Question 6
global_titles &lt;- NETFLIX_DATA |&gt;
  filter(avail_global == TRUE) |&gt; nrow()
total_titles &lt;- nrow(NETFLIX_DATA)

title_percent &lt;- global_titles/total_titles

global_hours &lt;- NETFLIX_DATA |&gt;
  filter(avail_global == TRUE) |&gt; 
  pull(hours_viewed) |&gt;
  sum()
total_hours &lt;- sum(NETFLIX_DATA$hours_viewed)

hours_percent &lt;- global_hours/total_hours



The date range covered by the data is from 2023-01-01 to 2026-06-30.
There are 61,892 different shows in this data set.
Viewers spent a total of 4,862,800,000 hours watching the Bridgerton universe of shows.
Viewers spent a total of 5,548,500,000 hours watching the original seasons of Stranger Things.
The Top 10 titles of the first half of 2026 account for 7% of total hours viewed during that period.
The percentage of Netflix’s catalog that is globally available by title is 35%, while the percentage that is globally available by hours viewed is 52%.
